const raw = $input.first().json;
let data = raw;
if (typeof raw === 'string') {
  try { data = JSON.parse(raw.replace(/^\)\]\}'/, '')); } catch (e) {}
}
const reviews = Array.isArray(data?.[1]?.[2]) ? data[1][2] : [];
const appId = String($input.first().json.appId || '');
if (!appId) return [{ json: { error: 'appId required' } }];
if (!reviews.length) return [{ json: { error: '리뷰 0건' } }];
const out = reviews.map(r => ({
  text: String(r?.[4] || ''),
  score: Number(r?.[0] || 0)
})).filter(x => x.text && x.score);
const low = out.filter(r => r.score <= 2).slice(0, 20);
const high = out.filter(r => r.score >= 4).slice(0, 20);
return [
  { json: { appId, direction: 'low', reviews: low, count: low.length } },
  { json: { appId, direction: 'high', reviews: high, count: high.length } }
];

const input = $input.first().json;
const direction = String(input.direction || '');
const reviews = Array.isArray(input.reviews) ? input.reviews : [];
const label = direction === 'low' ? '저평점 1~2점' : '고평점 4~5점';
const lines = reviews.map((r, i) => '[' + (i + 1) + '] (' + r.score + '점) ' + r.text).join('\n');
const promptText = 'Google Play 리뷰 분석. 기준: ' + label + '\n리뷰:\n' + lines + '\n\n출력:\n- 공통 불만:\n- 공통 칭찬:\n- 개선 요청 TOP5:';
const { execSync } = require('child_process');
let text = '';
try {
  const out = execSync('claude -p --model claude-sonnet-5', { input: promptText, encoding: 'utf8' });
  text = String(out || '');
} catch (e) {
  text = 'claude -p error: ' + e.message;
}
return [{ json: { text, direction } }];

const items = $input.all();
const appId = items[0]?.json?.appId || '';
const low = items.find(x => String(x.json.direction) === 'low');
const high = items.find(x => String(x.json.direction) === 'high');
const parse = (item) => String(item?.json?.text || '');
const parts = [];
if (low) parts.push('🔴 저평점(1~2점)\n' + parse(low));
if (high) parts.push('🟢 고평점(4~5점)\n' + parse(high));
const out = parts.join('\n\n');
return [{ json: { text: out || '분석 결과 없음', appId } }];
